#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        long long k, l;
        cin >> n >> k >> l;

        long long tide = k;
        bool possible = true;

        for (int i = 0; i < n; ++i) {
            long long depth;
            cin >> depth;

            if (depth + k <= l) {
                tide = k;
            } else {
                tide = min(tide - 1, l - depth);
                if (tide < 0) possible = false;
            }
        }

        cout << (possible ? "Yes" : "No") << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MM = 105;
const int INF = 0x3f3f3f3f;

int n, k, l, d[MM];
bool vis[MM][MM][2];

bool solve(int pos, int tide, bool increasing) {
    if (pos >= n + 1) return true;

    if (vis[pos][tide][increasing]) return false;
    vis[pos][tide][increasing] = true;

    int nextTide = tide + (increasing ? 1 : -1);
    bool nextIncreasing = increasing;

    if (nextTide == 0) nextIncreasing = true;
    else if (nextTide == k) nextIncreasing = false;

    for (int move = 0; move <= 1; ++move) {
        int nextPos = pos + move;
        if (d[nextPos] + nextTide <= l &&
            solve(nextPos, nextTide, nextIncreasing)) {
            return true;
        }
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        memset(vis, 0, sizeof(vis));

        cin >> n >> k >> l;
        for (int i = 1; i <= n; ++i) cin >> d[i];

        d[0] = d[n + 1] = -INF;

        cout << (solve(0, 0, true) ? "Yes" : "No") << '\n';
    }

    return 0;
}

