#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n, k, l;
        cin >> n >> k >> l;

        vector<int> d(n + 2, 0);
        for (int i = 1; i <= n; ++i) {
            cin >> d[i];
        }

        vector<vector<array<bool, 2>>> vis(
            n + 2, vector<array<bool, 2>>(k + 1, {false, false})
        );

        queue<tuple<int, int, int>> q;
        q.emplace(0, 0, 1);
        vis[0][0][1] = true;

        bool possible = false;

        while (!q.empty()) {
            auto [pos, tide, rising] = q.front();
            q.pop();

            if (pos == n + 1) {
                possible = true;
                break;
            }

            int nextTide, nextRising;

            if (k == 0) {
                nextTide = 0;
                nextRising = 1;
            } else {
                nextTide = tide + (rising ? 1 : -1);
                nextRising = rising;

                if (nextTide == 0)
                    nextRising = 1;
                else if (nextTide == k)
                    nextRising = 0;
            }

            for (int nextPos : {pos, pos + 1}) {
                bool safe = nextPos == 0 || nextPos == n + 1 ||
                            d[nextPos] + nextTide <= l;

                if (safe && !vis[nextPos][nextTide][nextRising]) {
                    vis[nextPos][nextTide][nextRising] = true;
                    q.emplace(nextPos, nextTide, nextRising);
                }
            }
        }

        cout << (possible ? "Yes" : "No") << '\n';
    }

    return 0;
}

